package cn.zhuatech.apimanagement;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.*;import java.util.regex.Pattern;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.httpBasic;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class DeepApiManagementTests{@Autowired MockMvc mvc;
 @Test void apiPublicationSubscriptionAndMetricsWork()throws Exception{long api=createApi("UT-API-01","JWT",1000),app=idOf(mvc.perform(post("/api/apim/apps").with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content("{\"organizationCode\":\"UT-APIM\",\"appCode\":\"UT-APP-01\",\"name\":\"订单应用\",\"owner\":\"应用负责人\"}")).andExpect(status().isOk()).andReturn());mvc.perform(post("/api/apim/apis/{id}/submit",api).with(httpBasic("operator","operator123"))).andExpect(status().isOk());mvc.perform(post("/api/admin/apim/apis/{id}/publish",api).with(httpBasic("admin","admin123"))).andExpect(status().isOk()).andExpect(jsonPath("$.data.status").value("PUBLISHED"));long sub=idOf(mvc.perform(post("/api/apim/subscriptions").with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content("{\"apiId\":"+api+",\"appId\":"+app+",\"environment\":\"PROD\",\"dailyQuota\":100000}")).andExpect(status().isOk()).andReturn());mvc.perform(post("/api/admin/apim/subscriptions/{id}/approve",sub).with(httpBasic("admin","admin123"))).andExpect(status().isOk()).andExpect(jsonPath("$.data.status").value("APPROVED"));mvc.perform(post("/api/apim/apis/{id}/metrics",api).with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content("{\"windowStart\":\"2026-08-27T10:00:00\",\"calls\":10000,\"errors\":5,\"p95LatencyMs\":280}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.health").value("HEALTHY"));mvc.perform(get("/api/apim/dashboard").param("organizationCode","UT-APIM").with(httpBasic("operator","operator123"))).andExpect(status().isOk()).andExpect(jsonPath("$.data.apis").isNotEmpty()).andExpect(jsonPath("$.data.health.calls").value(10000));}
 @Test void insecureApiCannotEnterReview()throws Exception{long id=createApi("UT-API-INSECURE","NONE",1000);mvc.perform(post("/api/apim/apis/{id}/submit",id).with(httpBasic("operator","operator123"))).andExpect(status().isConflict());}
 @Test void metricRejectsMoreErrorsThanCalls()throws Exception{long id=createApi("UT-API-METRIC","JWT",100);mvc.perform(post("/api/apim/apis/{id}/metrics",id).with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content("{\"windowStart\":\"2026-08-27T11:00:00\",\"calls\":10,\"errors\":11,\"p95LatencyMs\":100}")).andExpect(status().isBadRequest());}
 private long createApi(String code,String auth,int limit)throws Exception{return idOf(mvc.perform(post("/api/apim/apis").with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content("{\"organizationCode\":\"UT-APIM\",\"apiCode\":\""+code+"\",\"apiVersion\":\"v1\",\"name\":\"客户查询\",\"basePath\":\"/customers\",\"owner\":\"集成负责人\",\"authType\":\""+auth+"\",\"rateLimitPerMinute\":"+limit+"}")).andExpect(status().isOk()).andReturn());}private long idOf(MvcResult r)throws Exception{var m=Pattern.compile("\"id\":(\\d+)").matcher(r.getResponse().getContentAsString());Assertions.assertTrue(m.find());return Long.parseLong(m.group(1));}}
